:root{color-scheme:dark;--bg:#070a12;--panel:#0b1220;--panel2:#101d31;--line:#203653;--blue:#1677ff;--bright:#42a5ff;--text:#f4f8ff;--muted:#91a5c2}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 75% -10%,#10284d 0,transparent 35rem),var(--bg);color:var(--text);font:14px/1.5 Inter,"Segoe UI",Arial,sans-serif}a{color:inherit;text-decoration:none}button,textarea{font:inherit}.topbar{height:76px;border-bottom:1px solid #17416e;background:#050b16ee;display:flex;align-items:center;gap:28px;padding:0 28px;position:sticky;top:0;z-index:5}.brand{font-size:29px;font-weight:950;letter-spacing:-1.5px;white-space:nowrap}.brand span{color:var(--blue)}.search{max-width:530px;flex:1;border:1px solid #23456f;border-radius:99px;padding:12px 18px;background:#081326;color:#8ba7ce}.toplinks{margin-left:auto;display:flex;gap:18px;align-items:center;color:#8ebaff}.layout{display:grid;grid-template-columns:230px minmax(280px,380px) minmax(0,1fr);gap:0;max-width:1700px;margin:18px auto;padding:0 14px;height:calc(100vh - 110px);min-height:590px}.sidebar{padding:12px 12px 20px 0;border-right:1px solid var(--line);display:flex;flex-direction:column;gap:7px}.navlink{padding:12px 14px;border-radius:8px;color:#9bb4d8;font-weight:650;display:flex;align-items:center;gap:12px}.navlink:hover,.navlink.active{background:linear-gradient(90deg,#103d80,#0a1d3a);color:white;box-shadow:inset 3px 0 var(--blue)}.navicon{width:22px;text-align:center;color:#65aaff;font-size:18px}.promo{margin-top:auto;padding:18px;border:1px solid #1c477a;border-radius:12px;background:linear-gradient(145deg,#10294b,#080f1c)}.promo b{font-size:23px;line-height:1.1;display:block}.promo span{color:var(--bright)}.promo p{color:#91a9cb;font-size:12px}.inbox{border:1px solid var(--line);border-radius:13px 0 0 13px;overflow:hidden;background:#08101d;display:flex;flex-direction:column;min-height:0}.inboxhead{padding:21px 20px 15px;border-bottom:1px solid #172d49}.heading{font-size:21px;font-weight:850}.count{background:var(--blue);border-radius:20px;padding:2px 8px;font-size:11px;margin-left:6px}.filter{margin-top:13px;width:100%;border:1px solid #24466f;border-radius:99px;padding:10px 14px;background:#071327;color:var(--text);outline:none}.conversations{padding:7px 10px;overflow:auto}.item{display:flex;align-items:center;gap:10px;padding:12px 8px;border-bottom:1px solid #152741}.item:hover,.item.unread{background:linear-gradient(100deg,#0d2b59,#0a1525);border-radius:8px}.item.selected{background:linear-gradient(100deg,#0c3470,#0a1a30);box-shadow:inset 3px 0 var(--blue)}.avatar{width:42px;height:42px;flex:none;border-radius:50%;display:grid;place-items:center;border:1px solid #3277c0;background:linear-gradient(145deg,#163e6b,#10192b);color:#d5eaff;font-weight:850;font-size:16px}.details{min-width:0;flex:1}.name{font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.preview{font-size:12px;color:#8fa8cc;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:3px}.meta{font-size:11px;color:#7693ba;text-align:right}.badge{display:inline-block;margin-top:5px;background:var(--blue);border-radius:20px;min-width:20px;padding:1px 6px;text-align:center;color:white;font-size:11px}.chat{border:1px solid var(--line);border-left:0;border-radius:0 13px 13px 0;overflow:hidden;background:rgba(7,15,28,.96);display:flex;flex-direction:column;min-width:0;position:relative}.chat:before{content:"";position:absolute;inset:70px 0 75px;pointer-events:none;background:radial-gradient(ellipse at 90% 30%,#0c2a50aa,transparent 55%);opacity:.7}.chathead{z-index:1;padding:16px 22px;display:flex;align-items:center;gap:12px;border-bottom:1px solid var(--line);background:#07101feF}.person{min-width:0;flex:1}.person strong{font-size:17px}.person small{display:block;color:var(--muted);margin-top:2px}.online{display:inline-block;width:7px;height:7px;background:#35d49a;border-radius:50%;margin-right:5px}.chat-actions{display:flex;gap:8px;color:#65adff;font-size:19px}.chat-actions a{width:36px;height:36px;display:grid;place-items:center;border:1px solid transparent;border-radius:8px}.chat-actions a:hover{border-color:#244b7c;background:#0d2140}.subject{font-size:11px;color:#82a6d4;padding:7px 20px 0;z-index:1}.messages{position:relative;z-index:1;flex:1;display:flex;flex-direction:column;gap:14px;padding:18px 22px;overflow-y:auto;min-height:0;scroll-behavior:smooth}.day{text-align:center;font-size:11px;color:#84a0c6;padding:6px 12px;border:1px solid #203b60;border-radius:99px;background:#08152a;align-self:center;margin-bottom:2px}.message{max-width:min(78%,640px);align-self:flex-start}.message.mine{align-self:flex-end}.sender{font-size:11px;color:#8fa8cc;margin:0 0 4px 5px}.bubble{white-space:pre-wrap;overflow-wrap:anywhere;padding:12px 15px;border:1px solid #203a5e;background:linear-gradient(145deg,#12233d,#0d192d);border-radius:16px 16px 16px 4px;box-shadow:0 6px 18px #0002}.mine .bubble{background:linear-gradient(125deg,#0876ff,#0752c8);border-color:#2486ff;border-radius:16px 16px 4px 16px}.time{font-size:10px;color:#7794bc;margin:4px 5px 0}.composer{position:relative;z-index:2;padding:14px 18px 10px;border-top:1px solid var(--line);background:#080f1ef5;backdrop-filter:blur(14px)}.composer form{display:flex;align-items:flex-end;gap:10px}.composer textarea{flex:1;resize:none;min-height:48px;max-height:145px;padding:13px 15px;border:1px solid #24466f;border-radius:13px;background:#071327;color:var(--text);outline:none;overflow-y:auto}.composer textarea:focus{border-color:var(--bright);box-shadow:0 0 0 3px #1677ff22}.btn{width:49px;height:49px;flex:none;border:0;border-radius:50%;background:linear-gradient(145deg,#1682ff,#0756d3);color:#fff;font-size:20px;cursor:pointer;box-shadow:0 6px 18px #1677ff30}.btn:hover{filter:brightness(1.12)}.composer-hint{text-align:right;margin:6px 4px 0;color:#6f8bb1;font-size:10px}.error{color:#ffb4bc;font-size:12px;margin-top:5px}.flash{margin:10px 15px 0;padding:10px 12px;background:#0d2b25;border:1px solid #1f765d;color:#8cf0cb;border-radius:7px;z-index:2}
@media(max-width:1100px){.layout{grid-template-columns:65px 300px minmax(0,1fr)}.sidebar{align-items:center}.navlink{justify-content:center;width:48px;padding:12px}.navlabel,.promo,.search{display:none}.topbar{padding:0 18px}.messages{padding:14px}.chathead{padding:13px}.message{max-width:88%}}
@media(max-width:720px){.topbar{height:62px;padding:0 13px}.brand{font-size:25px}.toplinks{gap:10px}.layout{display:block;height:calc(100dvh - 74px);min-height:0;margin:8px;padding:0}.sidebar{display:none}.inbox{display:none}.chat{height:100%;border-left:1px solid var(--line);border-radius:12px}.chathead{padding:12px}.messages{padding:13px}.message{max-width:92%}.composer{padding:10px}.composer-hint{display:none}.btn{width:45px;height:45px}}
