<div class="composer"><form id="message-form" method="POST" action="{{ route('messages.store',$conversation) }}">@csrf<textarea id="message-body" name="body" required maxlength="5000" rows="1" placeholder="დაწერე შეტყობინება..." aria-label="შეტყობინება">{{ old('body') }}</textarea><button class="btn" type="submit" aria-label="შეტყობინების გაგზავნა">➤</button></form><div class="composer-hint">Ctrl + Enter · გაგზავნა</div>@error('body')<div class="error">{{ $message }}</div>@enderror</div>
</section></main><script>
const box=document.getElementById('messages');if(box&&!location.hash)box.scrollTop=box.scrollHeight;else if(location.hash){const target=document.querySelector(location.hash);target?.scrollIntoView({block:'center'})}
const body=document.getElementById('message-body');const form=document.getElementById('message-form');function resize(){body.style.height='auto';body.style.height=Math.min(body.scrollHeight,145)+'px'}body?.addEventListener('input',resize);body?.addEventListener('keydown',event=>{if(event.key==='Enter'&&(event.ctrlKey||event.metaKey)){event.preventDefault();form.requestSubmit()}});document.getElementById('conversation-search')?.addEventListener('input',event=>{const term=event.target.value.trim().toLocaleLowerCase();document.querySelectorAll('.item[data-search]').forEach(item=>item.hidden=!item.dataset.search.includes(term))});
</script></body></html>
